endpoint.response_schema:
- start: string (date-time)
- end: string (date-time)
- users: UserAcquisitionMetricsDTO { newUsersDaily, newUsersWeekly, newUsersMonthly, activatedUsersInRange, registrationSeries: TimeBucketMetricDTO[] }
- accessPlatforms: AccessPlatformMetricsDTO { successfulLogins, failedLogins, deviceDistribution: MetricCountDTO[], operatingSystemDistribution: MetricCountDTO[] }
- rentals: RentalConversionMetricsDTO { createdRentals, confirmedRentals, conversionRate }
- storageUploads: StorageUploadMetricsDTO { uploadedImages, totalBytes, averageBytes }
- criticalFailures: CriticalFailureMetricsDTO { totalFailures, failuresByType: MetricCountDTO[] }
